<?php
namespace App\Http\Controllers;
use App\Models\{Course,Lesson,Order};
use App\Services\CourseShop;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Schema};
use Illuminate\Support\Str;
class ShopController extends Controller {
 public function index(Request $r,CourseShop $shop){
  $data=$r->validate(['q'=>['nullable','string','max:120'],'category'=>['nullable','string','max:100']]);$keyword=trim($data['q']??'');$category=$data['category']??'';
  $query=Course::publishedOnline();
  $categoryName=\App\Models\LearningCategory::where('slug',$category)->value('name');
  $categories=\App\Models\LearningCategory::where('is_active',true)->whereHas('courses',fn($q)=>$q->publishedOnline())->orderBy('id')->get()->unique('name');
  $courses=$query->when($keyword!=='',fn($q)=>$q->where(fn($w)=>$w->where('name','like','%'.$keyword.'%')->orWhere('summary','like','%'.$keyword.'%')))->when($category!=='',fn($q)=>$q->whereHas('learningCategory',fn($c)=>$c->where('name',$categoryName??$category)))->with('learningCategory')->withCount(['lessons'=>fn($q)=>$q->where('is_published',true)])->orderBy('id')->paginate(30)->withQueryString();
  return view('learning.shop.catalog',compact('courses','keyword','shop','categories','category','categoryName'));
 }
 public function show(Course $course,Request $r,CourseShop $shop){abort_unless($course->delivery_mode==='online'&&$course->is_active&&$course->published_at?->lte(now()),404);$course->load(['sections.lessons'=>fn($q)=>$q->where('is_published',true)->orderBy('position')]);$owned=$r->user()&&$shop->owned($r->user(),$course->id);$buyable=$shop->available()->whereKey($course->id)->exists();$trialLessons=$course->lessons()->where('is_published',true)->where('is_preview',true)->orderBy('course_sections.position')->orderBy('lessons.position')->get();return view('learning.shop.course',compact('course','shop','owned','buyable','trialLessons'));}
 public function cart(Request $r,CourseShop $shop){$courses=$shop->cart($r->user());$token=$r->session()->get('checkout_token');if(!$token){$token=(string)Str::uuid();$r->session()->put('checkout_token',$token);}return view('learning.shop.cart',['courses'=>$courses,'shop'=>$shop,'token'=>$token,'signature'=>$shop->signature($courses)]);}
 public function clearCart(Request $r){DB::table('cart_items')->where('user_id',$r->user()->id)->delete();$r->session()->put('checkout_token',(string)Str::uuid());return redirect()->route('cart.index')->with('success','Đã xóa các khóa học khỏi giỏ hàng.');}
 public function checkoutForm(Request $r,CourseShop $shop){$courses=$shop->cart($r->user());if($courses->isEmpty())return redirect()->route('cart.index');$token=$r->session()->get('checkout_token');if(!$token){$token=(string)Str::uuid();$r->session()->put('checkout_token',$token);}return view('learning.shop.checkout',['courses'=>$courses,'shop'=>$shop,'token'=>$token,'signature'=>$shop->signature($courses)]);}
 public function selectCourse(Request $r,Course $course,CourseShop $shop){abort_unless($shop->available()->whereKey($course->id)->exists(),404);if($r->user())return redirect()->route('shop.show',$course->slug);$r->session()->put('pending_cart_course',$course->id);return redirect()->route('login')->with('success','Đăng nhập để thêm khóa học đã chọn vào giỏ.');}
 public function add(Request $r,Course $course,CourseShop $shop){abort_unless($shop->available()->whereKey($course->id)->exists(),404);if($shop->owned($r->user(),$course->id))return redirect()->route('account.courses')->with('success','Bạn đã có quyền học khóa này.');DB::table('cart_items')->insertOrIgnore(['user_id'=>$r->user()->id,'course_id'=>$course->id,'created_at'=>now(),'updated_at'=>now()]);$r->session()->put('checkout_token',(string)Str::uuid());return redirect()->route('cart.index')->with('success','Đã thêm khóa học vào giỏ.');}
 public function remove(Request $r,Course $course){DB::table('cart_items')->where('user_id',$r->user()->id)->where('course_id',$course->id)->delete();$r->session()->put('checkout_token',(string)Str::uuid());return back()->with('success','Đã bỏ khóa học khỏi giỏ.');}
 public function checkout(Request $r,CourseShop $shop){$d=$r->validate(['token'=>['required','uuid'],'signature'=>['required','string','size:64'],'buyer_name'=>['sometimes','required','string','max:255'],'buyer_email'=>['sometimes','required','email','max:255']]);abort_unless(hash_equals((string)$r->session()->get('checkout_token',''),$d['token']),419);$order=$shop->checkout($r->user(),$d['token'],$d['signature'],array_intersect_key($d,array_flip(['buyer_name','buyer_email'])));return redirect()->route('orders.show',$order->number);}
 public function orders(Request $r){if(!Schema::hasTable('orders'))return view('learning.shop.setup');$orders=Order::where('user_id',$r->user()->id)->withCount('items')->latest('id')->paginate(15);return view('learning.shop.orders',compact('orders'));}
 public function order(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);$order->load(['items','payment']);return view('learning.shop.order',compact('order'));}
 public function confirm(Request $r,Order $order,CourseShop $shop){abort_unless($order->user_id===$r->user()->id,404);abort_unless($order->payment->method==='demo',403);$d=$r->validate(['code'=>['required','string','max:40']]);$shop->confirm($order,$d['code'],$r->user());return redirect()->route('orders.show',$order->number)->with('success','Đã xác nhận thanh toán mô phỏng và cấp quyền học.');}
 public function qrReview(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);abort_unless($order->payment->method==='demo',403);abort_unless($r->hasValidSignature(false),403);$order->load(['items','payment']);return view('learning.shop.qr-confirm',compact('order'));}
 public function confirmQr(Request $r,Order $order,CourseShop $shop){abort_unless($order->user_id===$r->user()->id,404);abort_unless($order->payment->method==='demo',403);abort_unless($r->hasValidSignature(false),403);$shop->confirm($order,$order->payment->reference,$r->user());return redirect()->route('orders.show',$order->number)->with('success','Đã xác nhận thanh toán QR mô phỏng và cấp quyền học.');}
 public function bankQr(Request $r,Order $order,\App\Services\BankQr $bank){abort_unless($order->user_id===$r->user()->id,404);$qr=$bank->create($order);if($r->expectsJson())return response()->json(['reference'=>$qr->reference,'amount'=>$qr->amount,'bank'=>$qr->bank_snapshot,'image_url'=>$qr->imageUrl()])->header('Cache-Control','no-store');return redirect()->route('orders.show',$order->number);}
 public function reportTransfer(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);abort_unless($order->payment->method==='bank_transfer'&&$order->status==='pending',409);$d=$r->validate(['reference'=>['required','string','max:40']]);$qr=\App\Models\PaymentQrRequest::where('payment_id',$order->payment->id)->where('reference',$d['reference'])->firstOrFail();if(!$qr->reported_at)$qr->update(['reported_at'=>now()]);return back()->with('success','Đã báo admin kiểm tra giao dịch. Quyền học sẽ được cấp sau khi đối soát.');}
 public function status(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,404);return response()->json(['status'=>$order->status,'redirect'=>route('orders.show',$order->number)])->header('Cache-Control','no-store');}
 public function learn(Request $r,Course $course,CourseShop $shop){if($r->user()&&$shop->owned($r->user(),$course->id)){$lesson=$course->lessons()->where('is_published',true)->orderBy('course_sections.position')->orderBy('lessons.position')->first();return $lesson?redirect()->route('learn.lesson',[$course->slug,$lesson->id]):redirect()->route('account.courses')->with('error','Nội dung khóa học đang được cập nhật.');}$trial=$course->lessons()->where('is_published',true)->where('is_preview',true)->orderBy('course_sections.position')->orderBy('lessons.position')->first();if($trial){return redirect()->route('learn.lesson',[$course->slug,$trial->id]);}return redirect()->route('shop.show',$course->slug);}
 public function lesson(Request $r,Course $course,Lesson $lesson,CourseShop $shop){$isAllowed=($lesson->is_preview)||($r->user()&&$shop->owned($r->user(),$course->id));abort_unless($isAllowed&&$lesson->is_published&&$lesson->courseSection->course_id===$course->id,403);$course->load(['sections.lessons'=>fn($q)=>$q->where('is_published',true)->orderBy('position')]);$lesson->load(['examPapers'=>fn($q)=>$q->published()->whereHas('questions')]);$done=$r->user()?$r->user()->lessonProgress()->whereNotNull('completed_at')->pluck('lesson_id')->all():[];return view('learning.shop.lesson',compact('course','lesson','done'));}
 public function complete(Request $r,Course $course,Lesson $lesson,CourseShop $shop){abort_unless($r->user()&&$shop->owned($r->user(),$course->id)&&$lesson->is_published&&$lesson->courseSection->course_id===$course->id,403);$r->user()->lessonProgress()->updateOrCreate(['lesson_id'=>$lesson->id],['last_accessed_at'=>now(),'completed_at'=>now(),'position_seconds'=>$lesson->duration_seconds]);return back()->with('success','Đã ghi nhận hoàn thành bài học.');}
}

